// local reference. Optional layout evidence is verified when supplied and
// computed from exact bytes otherwise (including the Slice 1025 fixtures).
type OperationSource struct {
	SourceID     string                     `json:"source_id"`
	Role         SourceRole                 `json:"role"`
	ByteLength   uint64                     `json:"byte_length"`
	Sha256       string                     `json:"sha256"`
	Encoding     string                     `json:"encoding"`
	Content      *string                    `json:"content,omitempty"`
	Bytes        []byte                     `json:"bytes,omitempty"`
	Reference    *string                    `json:"reference,omitempty"`
	Bom          *bool                      `json:"bom,omitempty"`
	LineEndings  *LineEndings               `json:"line_endings,omitempty"`
	FinalNewline *bool                      `json:"final_newline,omitempty"`
	Extra        map[string]json.RawMessage `json:"extra,omitempty"`
}

// MarshalJSON serializes `[]byte` fields as a JSON array of integers (the format
// Rust's serde `Vec<u8>` deserializer expects) instead of Go's default base64 string.
func (v OperationSource) MarshalJSON() ([]byte, error) {
	// Explicit shadow struct listing every field — embedding the original
	// would cause both base64-string and int-array entries for the same JSON
	// key. Bytes fields rendered as `[]int`; everything else copied verbatim.
	aux := struct {
		SourceID     string                     `json:"source_id"`
		Role         SourceRole                 `json:"role"`
		ByteLength   uint64                     `json:"byte_length"`
		Sha256       string                     `json:"sha256"`
		Encoding     string                     `json:"encoding"`
		Content      *string                    `json:"content,omitempty"`
		Bytes        []int                      `json:"bytes"`
		Reference    *string                    `json:"reference,omitempty"`
		Bom          *bool                      `json:"bom,omitempty"`
		LineEndings  *LineEndings               `json:"line_endings,omitempty"`
		FinalNewline *bool                      `json:"final_newline,omitempty"`
		Extra        map[string]json.RawMessage `json:"extra,omitempty"`
	}{}
	aux.SourceID = v.SourceID
	aux.Role = v.Role
	aux.ByteLength = v.ByteLength
	aux.Sha256 = v.Sha256
	aux.Encoding = v.Encoding
	aux.Content = v.Content
	if v.Bytes != nil {
		aux.Bytes = make([]int, len(v.Bytes))
		for i, b := range v.Bytes {
			aux.Bytes[i] = int(b)
		}
	}
	aux.Reference = v.Reference
	aux.Bom = v.Bom
	aux.LineEndings = v.LineEndings
	aux.FinalNewline = v.FinalNewline
	aux.Extra = v.Extra
	return json.Marshal(aux)
}

